CREATE TABLE IF NOT EXISTS participants (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,telegram_user_id BIGINT NOT NULL,telegram_username VARCHAR(64) NULL,full_name VARCHAR(160) NOT NULL,phone VARCHAR(32) NOT NULL,instagram_handle VARCHAR(64) NOT NULL,status ENUM('active','blocked') NOT NULL DEFAULT 'active',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_participant_telegram(telegram_user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS telegram_user_sessions (telegram_user_id BIGINT NOT NULL PRIMARY KEY,step ENUM('awaiting_name','awaiting_phone','awaiting_instagram','awaiting_payment_receipt') NOT NULL,payload JSON NOT NULL,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS campaigns (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,slug VARCHAR(80) NOT NULL UNIQUE,title VARCHAR(180) NOT NULL,description TEXT NULL,status ENUM('draft','scheduled','open','paused','closed','drawn','archived') NOT NULL DEFAULT 'draft',participation_type ENUM('free','paid') NOT NULL DEFAULT 'free',entry_price BIGINT UNSIGNED NOT NULL DEFAULT 0,starts_at DATETIME NULL,ends_at DATETIME NULL,capacity INT UNSIGNED NULL,codes_per_entry SMALLINT UNSIGNED NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_campaign_status_dates(status,starts_at,ends_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS campaign_entries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,campaign_id BIGINT UNSIGNED NOT NULL,participant_id BIGINT UNSIGNED NOT NULL,profile_snapshot JSON NOT NULL,status ENUM('pending_payment','eligible','cancelled','disqualified') NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_campaign_participant(campaign_id,participant_id),KEY idx_entry_campaign_status(campaign_id,status),CONSTRAINT fk_entry_campaign FOREIGN KEY(campaign_id) REFERENCES campaigns(id),CONSTRAINT fk_entry_participant FOREIGN KEY(participant_id) REFERENCES participants(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS campaign_codes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,campaign_entry_id BIGINT UNSIGNED NOT NULL,campaign_id BIGINT UNSIGNED NOT NULL,code VARCHAR(32) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_campaign_code(campaign_id,code),UNIQUE KEY uq_entry_code(campaign_entry_id,code),CONSTRAINT fk_code_entry FOREIGN KEY(campaign_entry_id) REFERENCES campaign_entries(id),CONSTRAINT fk_code_campaign FOREIGN KEY(campaign_id) REFERENCES campaigns(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS payment_orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,campaign_entry_id BIGINT UNSIGNED NOT NULL UNIQUE,amount BIGINT UNSIGNED NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'IRR',status ENUM('awaiting_receipt','under_review','approved','rejected','cancelled') NOT NULL DEFAULT 'awaiting_receipt',expires_at DATETIME NULL,bank_name VARCHAR(80) NULL,card_number CHAR(16) NULL,card_holder VARCHAR(120) NULL,payment_instructions VARCHAR(500) NULL,rejection_reason VARCHAR(500) NULL,approved_by BIGINT NULL,approved_at DATETIME NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_order_entry FOREIGN KEY(campaign_entry_id) REFERENCES campaign_entries(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS payment_receipts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,telegram_file_id VARCHAR(255) NOT NULL,telegram_file_unique_id VARCHAR(255) NOT NULL,note VARCHAR(500) NULL,review_note VARCHAR(500) NULL,status ENUM('submitted','approved','rejected') NOT NULL DEFAULT 'submitted',reviewed_by BIGINT NULL,reviewed_at DATETIME NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_receipt_file(telegram_file_unique_id),KEY idx_receipt_order(order_id,status),CONSTRAINT fk_receipt_order FOREIGN KEY(order_id) REFERENCES payment_orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS profile_change_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,participant_id BIGINT UNSIGNED NOT NULL,requested_profile JSON NOT NULL,reason VARCHAR(500) NULL,status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',reviewed_by BIGINT NULL,reviewed_at DATETIME NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_profile_request_status(status,created_at),CONSTRAINT fk_profile_request_participant FOREIGN KEY(participant_id) REFERENCES participants(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS campaign_draws (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,campaign_id BIGINT UNSIGNED NOT NULL,status ENUM('prepared','completed','cancelled') NOT NULL DEFAULT 'prepared',algorithm VARCHAR(80) NOT NULL,seed_hash CHAR(64) NOT NULL,candidate_count INT UNSIGNED NOT NULL,created_by BIGINT NOT NULL,completed_at DATETIME NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_draw_campaign(campaign_id,created_at),CONSTRAINT fk_draw_campaign FOREIGN KEY(campaign_id) REFERENCES campaigns(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS draw_candidates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,draw_id BIGINT UNSIGNED NOT NULL,campaign_code_id BIGINT UNSIGNED NOT NULL,candidate_hash CHAR(64) NOT NULL,UNIQUE KEY uq_draw_candidate(draw_id,campaign_code_id),CONSTRAINT fk_candidate_draw FOREIGN KEY(draw_id) REFERENCES campaign_draws(id),CONSTRAINT fk_candidate_code FOREIGN KEY(campaign_code_id) REFERENCES campaign_codes(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS draw_winners (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,draw_id BIGINT UNSIGNED NOT NULL,campaign_code_id BIGINT UNSIGNED NOT NULL,rank_position SMALLINT UNSIGNED NOT NULL,UNIQUE KEY uq_draw_rank(draw_id,rank_position),UNIQUE KEY uq_draw_winner_code(draw_id,campaign_code_id),CONSTRAINT fk_winner_draw FOREIGN KEY(draw_id) REFERENCES campaign_draws(id),CONSTRAINT fk_winner_code FOREIGN KEY(campaign_code_id) REFERENCES campaign_codes(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_audit_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_telegram_id BIGINT NOT NULL,action VARCHAR(100) NOT NULL,entity_type VARCHAR(80) NOT NULL,entity_id BIGINT NULL,details JSON NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_audit_entity(entity_type,entity_id),KEY idx_audit_admin_time(admin_telegram_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_wizards (telegram_user_id BIGINT NOT NULL PRIMARY KEY,step ENUM('select_type','title','description','capacity','codes','price','confirm','payment_settings','payment_reject') NOT NULL,payload JSON NOT NULL,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS processed_updates (update_id BIGINT NOT NULL PRIMARY KEY,processed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS telegram_notification_outbox (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,chat_id BIGINT NOT NULL,payload JSON NOT NULL,status ENUM('pending','sending','sent','failed','uncertain') NOT NULL DEFAULT 'pending',attempts SMALLINT UNSIGNED NOT NULL DEFAULT 0,available_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,sent_at DATETIME NULL,locked_at DATETIME NULL,lease_token CHAR(36) NULL,last_error VARCHAR(500) NULL,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_outbox_delivery(status,available_at),KEY idx_outbox_lease(status,locked_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS payment_settings (id TINYINT UNSIGNED PRIMARY KEY,bank_name VARCHAR(80) NULL,card_number CHAR(16) NOT NULL,card_holder VARCHAR(120) NOT NULL,instructions VARCHAR(500) NULL,updated_by BIGINT NOT NULL,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS payment_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,actor_telegram_id BIGINT NOT NULL,event_type VARCHAR(40) NOT NULL,details JSON NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_payment_event_order(order_id,created_at),CONSTRAINT fk_payment_event_order FOREIGN KEY(order_id) REFERENCES payment_orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
